    token.free(token.handle);
  });

  bool get isClosed => _closed;

  void close() {
    if (_closed) {
      return;
    }
    _closed = true;
    _finalizer.detach(this);
    _ffi._sessionFree(_handle);
  }

  void _ensureOpen() {
    if (_closed) {
      throw StateError('Session is closed');
    }
  }

  Future<void> connect() {
    _ensureOpen();
    return _ffi.sessionInvokeConnect(_handle);
  }

  Future<bool> isHost() {
    _ensureOpen();
    return Future(() => _ffi.sessionInvokeIsHost(_handle));
  }

  Future<String?> nextRequest() {
    _ensureOpen();
    return _ffi.sessionInvokeNextRequest(_handle);
  }

  void respond(int id, String response) {
    _ensureOpen();
    _ffi.sessionInvokeRespond(_handle, id, response);
  }

  Future<String> send(String message) {
    _ensureOpen();
    return _ffi.sessionInvokeSend(_handle, message);
  }

  Future<String> sendWithTimeouts(String message, int ackTimeoutMs, int responseTimeoutMs) {
    _ensureOpen();
    return _ffi.sessionInvokeSendWithTimeouts(_handle, message, ackTimeoutMs, responseTimeoutMs);
  }

  Future<String> sessionId() {
    _ensureOpen();
    return _ffi.sessionInvokeSessionId(_handle);
  }

  Future<void> shutdown() {
    _ensureOpen();
    return _ffi.sessionInvokeShutdown(_handle);
  }

  Future<String> state() {
    _ensureOpen();
    return _ffi.sessionInvokeState(_handle);
  }

  Future<StateSubscription> subscribeStates() {
    _ensureOpen();
    return _ffi.sessionInvokeSubscribeStates(_handle);
  }

  Future<String> uri() {
    _ensureOpen();
    return _ffi.sessionInvokeUri(_handle);
  }

  Future<void> waitForLink() {
    _ensureOpen();
    return _ffi.sessionInvokeWaitForLink(_handle);
  }

}

