OpenlvFfiFfi? _defaultBindings;

OpenlvFfiFfi _bindings() => _defaultBindings ??= OpenlvFfiFfi();

void configureDefaultBindings({ffi.DynamicLibrary? dynamicLibrary, String? libraryPath}) {
  _defaultBindings = OpenlvFfiFfi(dynamicLibrary: dynamicLibrary, libraryPath: libraryPath);
}

void resetDefaultBindings() {
  _defaultBindings = null;
}

Future<Session> createDapp(String optionsJson) {
  return _bindings().createDapp(optionsJson);
}

Future<Session> createWallet(String uri, String peerInfoJson) {
  return _bindings().createWallet(uri, peerInfoJson);
}

Future<String> generateSessionId() {
  return _bindings().generateSessionId();
}

Future<String> parseSessionUri(String url) {
  return _bindings().parseSessionUri(url);
}

